import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/features/settings/pages/SettingsControls` — that file's `src` is claimed by TWO
// stored components (togglerow AND settingsrow), an ambiguous many-to-one mapping the preview's
// substitution resolver can't disambiguate, so a direct cross-import fails. Inlined instead.
function ToggleRow({ on, onToggle, title, children }) {
  return (
    <Row gap={12}>
      <Toggle on={on} onClick={onToggle} role="switch" ariaChecked={on} />
      <Box>
        <Text as="div" mono size={11.5} style={{ color: "var(--fg)", marginBottom: 2 }}>
          {title}
        </Text>
        <Box className="hint">{children}</Box>
      </Box>
    </Row>
  );
}

export function SoundNotificationsCard() {
  const [soundNotifications, setSoundNotifications] = useState(false);
  return (
    <Card title="Notification sounds" hint="opt-in — off by default">
      <ToggleRow
        on={soundNotifications}
        onToggle={() => setSoundNotifications(!soundNotifications)}
        title="Play a sound on fleet events"
      >
        Plays a short cue from the built-in <b>Signal</b> sound kit on key coordination events — a
        landing or merge chimes <code>success</code>, a failure chimes <code>error</code>, and a worker
        pausing for you chimes <code>notify</code>. Nothing plays until you enable it.
      </ToggleRow>
    </Card>
  );
}
